		\node[draw, text=black, minimum size=0.5cm, text width=1.5cm] (A) at (0,0) {Path\\Deviation};

		\node[draw, text=black, minimum size=0.5cm] (A1) at (1.8,1.25) {\textbf{FPV}};
		\node[draw, text=black, minimum size=0.5cm] (A2) at (1.8,0) {\textbf{GNSS}};
		\node[draw, text=black, minimum size=0.5cm] (A3) at (1.8,-1.25) {\textbf{GNSS+}};

		\node[draw, text=black, minimum size=0.5cm] (A10) at (3.65,1.25) {\textit{Single/Multiple}};

		\node[draw, text=black, minimum size=0.5cm] (A21) at (3.65,0.4) {\textit{Single}};
		\node[draw, text=black, minimum size=0.5cm] (A22) at (3.65,-0.4) {\textit{Multiple}};

		\node[draw, text=black, minimum size=0.5cm] (A31) at (3.65,-1.25) {\textit{Single}};

		\draw (A) -- (A1);
		\draw (A) -- (A2);
		\draw (A) -- (A3);

		\draw (A1) -- (A10);

		\draw (A2) -- (A21);
		\draw (A2) -- (A22);

		\draw (A3) -- (A31);

		\draw (A1) -- (A10);

		% FPS leaves
		\node[text=black, minimum size=0.5cm, anchor=west] (A10x) at (5.2,1.25) {\cite{shin2015security, pleban2014hacking, westerlund2019drone, dey2018security}};

		% GNSS single leaves
		\node[text=black, minimum size=0.5cm, anchor=west] (A21x) at (5.2,0.4) {\cite{khalajmehrabadi2018real, %hu2018gnss, 
		sun2018moving, liu2019analysis, xu2018performance, noh2019tractor}};
		% GNSS multi leaves
		\node[text=black, minimum size=0.5cm, anchor=west] (A22x) at (5.2,-0.4) {\cite{renyu2018spoofing, eldosouky2019drones}};

		% GNSS+ single leaves
		\node[text=black, minimum size=0.5cm, anchor=west] (A31x) at (5.2,-1.25) {\cite{qiao2017vision, varshosaz2020spoofing,melikhova2018optimum}};

		\draw [double,->] (A10) -- (A10x);

		\draw [double,->] (A21) -- (A21x);
		\draw [double,->] (A22) -- (A22x);

		\draw [double,->] (A31) -- (A31x);
	\end{tikzpicture}

\end{document}

