    \node (process3) [draw, below of=process2] {Process 3};
    \node (end) [draw, below of=process3] {End};

    \draw[->] (start) -- (process1);
    \draw[->] (process1) -- (process2);
    \draw[->] (process2) -- (process3);
    \draw[->] (process3) -- (end);
\end{tikzpicture}

\end{document}
